/*
 * LPC2148 SmartX Board - UART0 Serial Echo
 * Configures UART0 at 9600 baud using register-level access.
 * Opens Serial Monitor and types characters; the board echoes them.
 *
 * UART0 pins: P0.2 = TXD0, P0.3 = RXD0
 */

#include <LPC214x.h>

unsigned char msg[] = {'L','P','C','2','1','4','8',' ','U','A','R','T','0',' ','E','c','h','o','\r','\n',0};

void uart0_init(unsigned int baud) {
    unsigned int divisor = 15000000 / (16 * baud);
    PINSEL0 |= (1 << 1);
    PINSEL0 &= ~(1 << 2);
    PINSEL0 |= (1 << 7);
    PINSEL0 &= ~(1 << 6);
    U0LCR = 0x83;
    U0DLL = divisor & 0xFF;
    U0DLM = (divisor >> 8) & 0xFF;
    U0LCR = 0x03;
    U0FCR = 0x07;
}

void uart0_tx(unsigned char ch) {
    while (!(U0LSR & 0x20));
    U0THR = ch;
}

int main() {
    unsigned int i;
    uart0_init(9600);
    i = 0;
    while (msg[i] != 0) {
        uart0_tx(msg[i]);
        i++;
    }
    while (1) {
        if (U0LSR & 0x01) {
            unsigned char ch = U0RBR;
            uart0_tx(ch);
        }
        delay_ms(10);
    }
}
